// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // fuzzed caller address; the reference should always return the stored owner (deployer),
    // whereas the mutant (returning _msgSender()) will for some callers return the caller instead,
    // causing a mismatch. We expose this by calling owner() under a prank from the fuzzed address
    // and asserting that owner() equals the deployer (address(this) from setUp()).
    function testFuzz_property(address caller) public {
        // keep wide domain but avoid the zero address just to be safe
        vm.assume(caller != address(0));

        // call owner() as the fuzzed caller
        vm.prank(caller);
        address reported = c.owner();

        // General rule: the stored owner (deployer) must be returned for any caller.
        // In the reference this holds for all callers; the mutant that returns msg.sender will
        // for some callers (any caller != deployer) return a different address and thus fail this assert.
        assertTrue(reported == address(this));
    }
}

