pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // fuzz parameter: address newOwner (fuzzer will try address(0) among others)
    function testFuzz_property(address newOwner) public {
        // keep domain wide; ensure caller is the owner (setUp made address(this) the owner)
        // We'll try calling transferOwnership as the owner and observe whether it succeeds.

        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: reference implementation reverts when newOwner == address(0).
        // So for all inputs, ok must be false if newOwner == address(0).
        // The mutant removes the require and will make ok true for newOwner == address(0) for some runs.
        if (newOwner == address(0)) {
            assertTrue(!ok);
        }
        // If newOwner != address(0) we make no assertion (keeps test universal for reference).
    }
}

