    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // fuzz newOwner; for the correct contract transferOwnership(address(0)) must revert,
    // while the mutant will allow it. We let the fuzzer supply arbitrary addresses.
    function testFuzz_property(address newOwner) public {
        // keep domain wide: no vm.assume except ensure caller is current owner (setUp deployer)
        // Caller is address(this) already (deployer and owner), so we call directly.

        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: on the correct contract, the call should revert exactly when newOwner is zero.
        // Since this test runs against the reference C, for ALL inputs it must hold: ok == (newOwner != address(0)).
        // The mutant breaks this for newOwner == address(0) (it would set owner to zero and return ok==true).
        assertTrue(ok == (newOwner != address(0)));
    }
