pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), address(this)); }

    // fuzzed parameters: newOwnerCandidate and caller (the owner)
    // We fuzz two addresses so fuzzer can find a newOwner different from current owner.
    function testFuzz_property(address newOwnerCandidate, address caller) public {
        // Keep addresses admissible: caller must be non-zero and distinct from tx.origin zero address edge-case
        vm.assume(caller != address(0));
        // Make sure the caller is the owner in the scenario: deployer (this) is initial owner per constructor
        // So we impersonate the owner (address(this) in test) when calling transferOwnership.
        // But to allow fuzzing over the new owner candidate, we use that param directly.

        // The general rule: when the caller is the current owner, transferOwnership(newOwner) should succeed (not revert).
        // We simulate the current owner calling transferOwnership with the fuzzed newOwnerCandidate.

        bool ok;
        try c.transferOwnership{ }(newOwnerCandidate) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract always allows the current owner to change ownership to any non-zero address.
        // However, if the mutant adds the extra require(newOwner == owner()), then when newOwnerCandidate != owner()
        // the mutant will revert while the reference would succeed. We express a universal property that the reference
        // satisfies for all inputs: when the caller is the current owner and newOwnerCandidate is non-zero, the call
        // does not revert and owner() equals newOwnerCandidate afterwards.
        // We must fuzz newOwnerCandidate; to avoid the reference reverting on zero address we exclude it here.
        vm.assume(newOwnerCandidate != address(0));

        // Assert the reference behavior: call succeeded and owner() equals newOwnerCandidate.
        // Note: In the buggy mutant, when newOwnerCandidate != current owner, the call will revert and ok==false,
        // causing this assertTrue to fail for those inputs. For the reference, ok will always be true and owner()
        // will match newOwnerCandidate.
        assertTrue(ok && c.owner() == newOwnerCandidate);
    }
}

