pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), address(this)); }

    // fuzzed params: newOwnerCandidate and a boolean to decide whether the caller is owner or not
    function testFuzz_property(address newOwnerCandidate, bool callerIsOwner) public {
        // keep addresses wide but avoid the zero-address as an invalid target for transferOwnership
        // (the contract itself rejects zero address). Allow fuzzer to still try zero to explore behaviour,
        // but we will skip that case because both ref and mutant reject it (not useful to differentiate mutant).
        // Also bound newOwnerCandidate to avoid special reserved addresses in forge (not necessary but ok).
        // Ensure the test exercises the case where msg.sender is the owner vs non-owner.

        // decide who will call transferOwnership
        address caller = callerIsOwner ? address(this) : address(0xBEEF);

        // if newOwnerCandidate is zero, both versions revert; skip to keep property meaningful
        if (newOwnerCandidate == address(0)) return;

        // ensure caller has the right sender context
        if (caller == address(this)) {
            // current owner is address(this) as set in setUp
            // attempt transferOwnership as owner
            bool ok;
            try c.transferOwnership(newOwnerCandidate) {
                ok = true;
            } catch {
                ok = false;
            }

            // General rule: when caller is the current owner, the correct contract will accept any non-zero newOwner
            // and thus transferOwnership should succeed (ok == true). The mutant reverts whenever newOwnerCandidate
            // != current owner, causing ok == false for some inputs — our assertion checks the success flag.
            assertTrue(ok);
        } else {
            // non-owner caller: both correct and mutant should revert due to onlyOwner modifier.
            // We simply call from the non-owner and assert that the call reverts (i.e., does not succeed).
            vm.prank(caller);
            bool ok;
            try c.transferOwnership(newOwnerCandidate) {
                ok = true;
            } catch {
                ok = false;
            }
            // For non-owner, transferOwnership must revert (ok == false)
            assertTrue(!ok);
        }
    }
}

