pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), address(this)); }

    // Fuzzed parameter: an arbitrary address that will attempt to call transferOwnership via a forwarding contract
    function testFuzz_property(address caller, address newOwner) public {
        // keep addresses non-zero to be meaningful
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        // Deploy a forwarder contract that will call c.transferOwnership on behalf of caller
        Forwarder f = new Forwarder();

        // Ensure the forwarder calls transferOwnership with tx.origin == caller by making caller be an EOA that does the external call
        // We cannot make the fuzzer control EOA private key, but vm.prank sets msg.sender for the next call, and tx.origin will be that same EOA
        // So we prank as 'caller' to perform the external call to the forwarder which then forwards to c

        // First, record whether direct call from caller would succeed (reference requires owner()==msg.sender)
        bool directOk;
        // try direct invocation: prank as caller and call c.transferOwnership
        vm.prank(caller);
        try c.transferOwnership(newOwner) {
            directOk = true;
        } catch {
            directOk = false;
        }

        // Now, attempt via forwarder: prank as caller so tx.origin == caller, but msg.sender at c will be forwarder
        bool viaForwarderOk;
        vm.prank(caller);
        try f.forwardTransferOwnership(address(c), newOwner) {
            viaForwarderOk = true;
        } catch {
            viaForwarderOk = false;
        }

        // General rule for reference: directOk == viaForwarderOk always, because onlyOwner uses msg.sender; a forwarded call shouldn't succeed if direct did not.
        // The mutant (owner checked against tx.origin) will make viaForwarderOk==true while directOk==false for some inputs.
        // We assert that directOk == viaForwarderOk. This holds for reference for ALL inputs, but will be violated by the mutant for some inputs.
        assertTrue(directOk == viaForwarderOk);
    }
}

// Minimal forwarder that calls transferOwnership on target C
contract Forwarder {
    function forwardTransferOwnership(address target, address newOwner) external {
        C(target).transferOwnership(newOwner);
    }
}

