pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Forwarder f;

    function setUp() public { c = new C(address(this), address(this)); }

    // fuzzed params: ownerSeed is used to pick an address that will become owner; newOwner is the target passed to transferOwnership
    function testFuzz_property(uint256 ownerSeed, address newOwner) public {
        // Keep domains wide but avoid zero newOwner (owner transfer to zero is rejected in reference)
        // Allow ownerSeed to generate many possible addresses via vm.addr
        address ownerCandidate = vm.addr(ownerSeed);
        vm.assume(newOwner != address(0));

        // Make ownerCandidate the owner by having ownerCandidate deploy the contract via a prank that calls transferOwnership
        // Initially contract owner is address(this). We want to transfer ownership to ownerCandidate so that owner() == ownerCandidate.
        // Only current owner (address(this)) can call transferOwnership on reference, so do it directly here.
        c.transferOwnership(ownerCandidate);
        assertTrue(c.owner() == ownerCandidate);

        // Deploy a forwarding contract from ownerCandidate so tx.origin == ownerCandidate when it calls out
        vm.prank(ownerCandidate);
        f = new Forwarder();

        // Now attempt to have the forwarder call transferOwnership to set owner to newOwner.
        // In the reference, only calls with msg.sender == ownerCandidate succeed. The forwarder will call with msg.sender == address(f)
        // so the reference should revert and the call should fail; the mutant (checking tx.origin) would succeed because tx.origin==ownerCandidate.

        bool ok;
        // instruct forwarder to call c.transferOwnership(newOwner)
        vm.prank(address(f));
        try f.doTransferOwnership(address(c), newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The single assertion: reference property is that the forwarder-call must NOT succeed (ok == false) for ALL inputs.
        // The mutant (which checks tx.origin) will allow the forwarder to succeed for some inputs (when tx.origin==ownerCandidate), causing this assertion to fail.
        assertTrue(!ok);
    }
}

// Minimal forwarder that simply forwards a call to transferOwnership
contract Forwarder {
    function doTransferOwnership(address target, address newOwner) public {
        // low-level call to propagate caller as this contract (msg.sender != tx.origin)
        (bool success, ) = target.call(abi.encodeWithSignature("transferOwnership(address)", newOwner));
        require(success, "forward failed");
    }
}

