pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), address(this)); }

    // fuzz owner (an EOA that will be the owner) and newOwner (the address to transfer ownership to)
    function testFuzz_property(address ownerEOA, address newOwner) public {
        // keep addresses non-zero and distinct to be meaningful
        vm.assume(ownerEOA != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(ownerEOA != newOwner);

        // Step 1: make ownerEOA the owner by deploying a small helper that will set owner via transferOwnership called by current owner (which is this contract)
        // We need ownerEOA to be owner() in the contract c. The constructor set owner to address(this). Use transferOwnership to set to ownerEOA.
        // Only current owner (this) can call transferOwnership on the reference, so do it now as this.
        c.transferOwnership(ownerEOA);

        // Verify owner was set correctly (reads public owner()) - this must hold on reference for all inputs
        assertTrue(c.owner() == ownerEOA);

        // Now prepare a forwarding contract that will call c.transferOwnership(newOwner) as a contract, with tx.origin == ownerEOA
        Forwarder f = new Forwarder();

        // Fund the ownerEOA EOA so it can be tx.origin for a prank; use vm.deal to assign some ETH to ownerEOA
        vm.deal(ownerEOA, 1 ether);

        // The forwarding contract will perform a call to c.transferOwnership(newOwner)
        // We want tx.origin == ownerEOA and msg.sender == address(f). That means we must have ownerEOA externally call f which in turn calls c.
        // Use vm.prank to set tx.origin and msg.sender for the external call into f: vm.prank sets msg.sender for the next call from the EVM test account; to simulate an EOA calling f we use vm.prank(ownerEOA) then call f.forwardTransferOwnership

        // Execute forwarding: ownerEOA (EOA) calls f which calls c.transferOwnership(newOwner)
        vm.prank(ownerEOA);
        f.callTransferOwnership(address(c), newOwner);

        // Now check whether ownership changed to newOwner. On the correct contract this MUST be false because msg.sender inside transferOwnership was address(f), not ownerEOA.
        // The single required assertion reads c's public getter and will fail on the mutant where tx.origin check allows this forwarded call to succeed; it must pass on the reference for ALL inputs.
        assertTrue(c.owner() != newOwner);
    }
}

// Minimal forwarding helper: simply calls transferOwnership on target as a contract
contract Forwarder {
    function callTransferOwnership(address target, address newOwner) external {
        C(target).transferOwnership(newOwner);
    }
}

