pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), address(this)); }

    // fuzz parameters: an owner EOA and an arbitrary candidate newOwner
    function testFuzz_property(address ownerEOA, address newOwner) public {
        // keep ownerEOA non-zero and distinct from test contract to be meaningful
        vm.assume(ownerEOA != address(0));
        vm.assume(ownerEOA != address(this));
        // deploy a forwarder contract that will call c.transferOwnership(newOwner) when instructed
        Forwarder f = new Forwarder();

        // ensure the Forwarder exists (always true) and newOwner is non-zero
        vm.assume(newOwner != address(0));

        // 1) set ownerEOA as the owner of c by constructing c with owner = address(this) initially,
        // so we need to transfer ownership from address(this) -> ownerEOA using a direct call from address(this)
        // onlyOwner requires msg.sender == owner() and in setup owner() == address(this), so this succeeds.
        c.transferOwnership(ownerEOA);
        // sanity: owner should now be ownerEOA
        assertTrue(c.owner() == ownerEOA);

        // Now, we simulate two attempts to call transferOwnership to set owner to newOwner:
        // A) Direct call by the ownerEOA (prank as ownerEOA) -> should succeed on reference
        vm.startPrank(ownerEOA);
        bool okDirect;
        try c.transferOwnership(newOwner) {
            okDirect = true;
        } catch {
            okDirect = false;
        }
        vm.stopPrank();

        // restore owner back to ownerEOA if direct succeeded (so subsequent forwarded call sees same starting owner)
        if (okDirect) {
            // transfer back from newOwner to ownerEOA via direct call as newOwner only if newOwner is EOA we control.
            // But we cannot assume newOwner is an EOA we control, so instead, if direct succeeded owner changed and
            // we cannot revert state — to keep domain wide, we require that direct call did NOT succeed when
            // invoked by ownerEOA in a way that would interfere with the forwarded scenario. We restrict inputs
            // so ownerEOA's direct attempt does NOT change owner: i.e., we only consider cases where ownerEOA's
            // direct transfer did NOT succeed, which happens only if ownerEOA is not able to call (rare). To avoid
            // complicating control flow, we constrain that ownerEOA's direct attempt fails by requiring ownerEOA
            // is not a contract (an EOA) — but fuzz provides EOAs only. Simpler: we revert any changes by redeploying c.

            // Redeploy fresh contract to reset ownership to address(this) and then set ownerEOA again.
            c = new C(address(this), address(this));
            c.transferOwnership(ownerEOA);
            assertTrue(c.owner() == ownerEOA);
        }

        // At this point, ensure owner is ownerEOA
        assertTrue(c.owner() == ownerEOA);

        // B) Forwarded call: ownerEOA (EOA) will call the Forwarder, which will in turn call c.transferOwnership(newOwner)
        // This means tx.origin == ownerEOA but msg.sender in c will be the Forwarder address.
        vm.prank(ownerEOA);
        bool okForwarded = f.forwardTransferOwnership(address(c), newOwner);

        // The GENERAL PROPERTY we assert: In the correct contract, a forwarded call where msg.sender != owner must NOT succeed.
        // We observe success/failure by checking whether owner changed to newOwner.
        // Because we must provide exactly one assertion reading c, assert that owner remains ownerEOA.
        assertTrue(c.owner() == ownerEOA);
    }
}

// Minimal forwarder that simply calls transferOwnership on target contract and returns whether it succeeded
contract Forwarder {
    function forwardTransferOwnership(address target, address newOwner) external returns (bool) {
        (bool success, ) = target.call(abi.encodeWithSelector(C.transferOwnership.selector, newOwner));
        return success;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // Fuzzed params: ownerEOA is the EOA that will be set as owner (pranked), forwardIsOwner indicates
    // whether the forwarder will be the owner EOA (used to create cases); newOwner is the target ownership
    // address passed to transferOwnership. The fuzzer will search addresses to find a case where forwarding
    // causes the mutant to differ.
    function testFuzz_property(address ownerEOA, bool forwardIsOwner, address newOwner) public {
        // Keep parameters wide but avoid zero newOwner (transferOwnership requires non-zero in reference)
        if (newOwner == address(0)) return;

        // Deploy a simple forwarder that will call c.transferOwnership on behalf of its caller
        Forwarder f = new Forwarder();

        // Decide who will be the owner EOA in this scenario: either the forwarder contract or a supplied EOA
        address initialOwner = forwardIsOwner ? address(f) : ownerEOA;

        // Set the contract owner to initialOwner by simulating the constructor behavior: contract's constructor set owner to address(this).
        // We cannot change that, so instead we transfer ownership from current owner (this test contract) to initialOwner.
        // The current owner is address(this) because setUp used address(this) as owner parameter when deploying C.
        // So perform a direct call from this test contract to transfer ownership to initialOwner.
        c.transferOwnership(initialOwner);

        // Now attempt to call transferOwnership via the forwarder: we want to observe whether a forwarded call
        // (msg.sender == forwarder, tx.origin == the EOA that initiated the transaction) succeeds or reverts.
        // We will have an EOA caller be "ownerEOA" (the fuzzed parameter) perform the external call into the forwarder.

        // Prepare the low-level call from the EOA ownerEOA: fund it and prank as that EOA.
        vm.deal(ownerEOA, 1 ether);
        vm.prank(ownerEOA);
        bool ok;
        try f.forwardTransferOwnership(address(c), newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // Now, the universal property: In the reference contract, transferOwnership can only succeed when msg.sender == owner().
        // A forwarded call from an EOA ownerEOA through the forwarder will have msg.sender == address(forwarder), so it should
        // NOT succeed on the reference contract unless the forwarder itself is the owner (i.e., initialOwner == address(f)).
        // Therefore the invariant we assert is:
        //   If the contract's current owner is not the forwarder, then the forwarded call must have failed (ok == false).
        // This holds for the reference for ALL inputs. The mutant that checks tx.origin instead of msg.sender will allow the
        // forwarded call to succeed when tx.origin == initialOwner (i.e., ownerEOA == initialOwner in the case forwarder is not owner),
        // so there exist inputs where ok == true on the mutant but false on the reference.

        bool forwarderIsOwner = (c.owner() == address(f));

        // Single assertion reading c (owner getter) and the observed ok flag from the attempted forwarded call.
        // This asserts: if forwarder is not the owner, forwarded attempt must have failed.
        assertTrue(forwarderIsOwner || !ok);
    }
}

// Minimal forwarder that simply forwards the call to transferOwnership on target
contract Forwarder {
    function forwardTransferOwnership(address target, address newOwner) external {
        // forward a call to transferOwnership on target
        (bool success, ) = target.call(abi.encodeWithSelector(bytes4(keccak256("transferOwnership(address)")), newOwner));
        require(success, "forward failed");
    }
}

contract InvMutTest {
    C public c;

    constructor(C _c) {
        c = _c;
    }

    // single public function executing the test
    function run(address newDistributor) public {
        // Capture precondition: caller must be owner to succeed
        // ensure msg.sender is owner of c; if not, setOwner cannot be called here, so require externally
        // perform the state-changing call under test
        c.setRewardDistributor(newDistributor);

        // Observe resulting distributor via public getter
        address resulting = c.rewardDistributor();

        // The correct behavior (original) sets rewardDistributor to the provided argument
        assert(resulting == newDistributor);
    }

    // allow receiving ETH if needed by the environment
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address distributor) public payable {
        // require that the caller is not equal to tx.origin to expose mutant behavior when tx.origin is used
        require(msg.sender != tx.origin, "need msg.sender != tx.origin");
        c.setRewardDistributor(distributor);
        // In the original, rewardDistributor should equal the supplied _distributor (since onlyOwner sets it to the arg).
        // In the mutant, it would be set to tx.origin (an attacker-controlled different value when msg.sender != tx.origin).
        assert(c.rewardDistributor() == distributor || c.rewardDistributor() == msg.sender);
    }
    receive() external payable { }
}
